5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
7	
8	/**
9	 * Runs in {@code POST /api/owners} before any entity is built or persisted. Rejects the
10	 * request when the current day has already reached {@link #DAILY_LIMIT} owner registrations
11	 * (counted by {@code registrationDate}), throwing {@link DailyOwnerLimitException} for a 429.
12	 * Reads the count in the same transaction as the writes so the per-day cap is enforced
13	 * consistently.
14	 */
15	public class EnsureDailyOwnerCapacity {
16	
17	    /** Maximum number of owners that may be registered in a single day. */
18	    static final int DAILY_LIMIT = 100;
19	
20	    public void service(OwnerRepository ownerRepository) throws DailyOwnerLimitException {
21	
22	        LocalDate today = LocalDate.now();
23	        long todayCount = ownerRepository.findAll().stream()
24	                .filter(existing -> today.equals(existing.getRegistrationDate()))
25	                .count();
26	        if (todayCount >= DAILY_LIMIT) {
27	            throw new DailyOwnerLimitException(today);
28	        }
29	    }
30	}
