5	/**
6	 * Thrown by the create-owner pipeline when the current day has already reached the maximum
7	 * number of owner registrations (the per-day limit), so no further owner may be registered
8	 * today. Carries the day so {@link DailyOwnerLimitExceptionHandler} can report it. Handled as
9	 * 429 Too Many Requests.
10	 */
11	public class DailyOwnerLimitException extends Exception {
12	
13	    private final LocalDate date;
14	
15	    public DailyOwnerLimitException(LocalDate date) {
16	        super("Daily owner registration limit reached for: " + date);
17	        this.date = date;
18	    }
19	
20	    public LocalDate getDate() {
21	        return this.date;
22	    }
23	}
