4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	/**
10	 * Responds 429 Too Many Requests when a create request arrives after the current day has
11	 * already reached its maximum number of owner registrations.
12	 */
13	public class DailyOwnerLimitExceptionHandler {
14	
15	    public void handle(@Parameter DailyOwnerLimitException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.TOO_MANY_REQUESTS,
18	                "The maximum number of owners for today has been reached");
19	        response.send(ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(detail));
20	    }
21	}
