53	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
54	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
55	        return unique && hasEmail ? "SILVER" : "BRONZE";
56	    }
